 public const string Folder="TruckWifeCarrying",Scene="Assets/TruckWifeCarrying/Scenes/TruckWifeCarrying.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<WifeMatch>(Folder);m.setup.count=8;m.option=0;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();var course=m.gameObject.AddComponent<WifeCourse>();m.course=course;string path="Assets/"+Folder+"/Materials/Partner obstacle meadow.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,path);}data.heightmapResolution=257;data.size=new Vector3(530,25,400);data.terrainLayers=new[]{AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer"),AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer")};data.alphamapResolution=128;var alpha=new float[128,128,2];for(int z=0;z<128;z++)for(int x=0;x<128;x++){float wz=-20+z/127f*400;bool mud=wz>110&&wz<150||wz>205&&wz<227;alpha[z,x,1]=mud?.85f:.08f;alpha[z,x,0]=1-alpha[z,x,1];}data.SetAlphamaps(0,0,alpha);var heights=new float[257,257];for(int z=0;z<257;z++)for(int x=0;x<257;x++){float wz=-20+z/256f*400,wx=-265+x/256f*530;float bank=Mathf.Min(60,Mathf.Max(0,Mathf.Abs(wx-course.Center(wz))-29));float h=4+Mathf.Sin(wz*.025f)*.75f+bank*bank*.004f+Mathf.Sin(wx*.15f+wz*.07f)*Mathf.SmoothStep(0,.45f,Mathf.InverseLerp(15,60,wz));float dz=(wz-84)/6;h+=.55f*Mathf.Exp(-dz*dz);dz=(wz-187)/5;h+=.7f*Mathf.Exp(-dz*dz);if(wz>205&&wz<227)h-=.20f;heights[z,x]=h/25;}data.SetHeights(0,0,heights);course.terrain=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();course.terrain.name="Partner carrying banked slalom meadow";course.terrain.transform.position=new Vector3(-265,-4,-20);course.terrain.drawInstanced=true;var terrainMat=SportsEventAuthoring.Mat(Folder,"Partner grass and mud",Color.white);terrainMat.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");course.terrain.materialTemplate=terrainMat;
 m.pairs=new WifePair[4];m.identities=new TextMesh[4];for(int i=0;i<4;i++){var driver=SportsEventAuthoring.Truck(m,Folder,"Pair "+(i+1)+" driver",course.Spawn(i),i);SportsRallyAuthoring.FitTruck(driver);driver.maxSpeed=18;driver.steerAngle=34;driver.body.centerOfMass=new Vector3(0,-.15f,0);var passenger=SportsEventAuthoring.Truck(m,Folder,"Pair "+(i+1)+" smaller passenger",Vector3.zero,i+4);SportsRallyAuthoring.FitTruck(passenger);var binding=passenger.GetComponent<SportsWheelMeshBinding>();for(int w=0;w<4;w++){var physical=passenger.wheels[w].wheel.rotatingContainer;binding.meshes[w].rotation=physical.rotation*binding.alignment[w];binding.meshes[w].position=physical.position-binding.meshes[w].TransformVector(binding.centers[w]);}UnityEngine.Object.DestroyImmediate(binding);passenger.transform.localScale=Vector3.one*.55f;passenger.body.mass=2.5f;passenger.body.solverIterations=16;passenger.body.solverVelocityIterations=8;passenger.Power(false);passenger.engine.enabled=false;var pair=driver.gameObject.AddComponent<WifePair>();pair.driver=driver;pair.passenger=passenger;pair.match=m;pair.slot=i;pair.roofAnchor=new Vector3(0,driver.shape.center.y+driver.shape.size.y*.5f+.17f-(passenger.shape.center.y-passenger.shape.size.y*.5f)*.55f,0);passenger.transform.SetPositionAndRotation(driver.transform.TransformPoint(pair.roofAnchor),driver.transform.rotation);pair.cradle=new GameObject("Visible pallet roof cradle and padded rails").transform;pair.cradle.SetParent(driver.transform,false);pair.cradle.localPosition=new Vector3(0,driver.shape.center.y+driver.shape.size.y*.5f,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(pair.cradle,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Pallet Variant.prefab",new Vector3(1.6f,.16f,1.7f),0,true);var straps=SportsEventAuthoring.Mat(Folder,"Safety webbing",new Color(.85f,.24f,.12f));pair.straps=new LineRenderer[2];for(int side=0;side<2;side++){var line=new GameObject("Physical cradle tether visual "+side).AddComponent<LineRenderer>();line.transform.SetParent(pair.cradle,false);line.sharedMaterial=straps;line.positionCount=3;line.startWidth=line.endWidth=.055f;line.enabled=false;pair.straps[side]=line;}m.pairs[i]=pair;m.identities[i]=SportsEventAuthoring.Label("Pair identity "+i,m.teams[i],passenger.transform.position+Vector3.up,.10f,m.setup.players[i].color);var billboard=m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();billboard.distanceSizing=true;billboard.referenceDistance=30;}
 m.views=SportsRallyAuthoring.Views(m,m.pairs.Select(pair=>pair.driver).ToArray());m.views.groundOffset=new Vector3(0,6,-13);m.views.groundLookAhead=4;m.views.groundFov=65;course.weather=SportsChaosAuthoring.Weather(m,Folder);m.views.weather=course.weather;course.weather.Configure(39,1,0);Dress(m);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);m.roleLabels=new TMP_Text[8];for(int i=0;i<8;i++)m.roleLabels[i]=SportsUIAuthoring.Text("Pair role "+i,m.menus.rows[i].transform,"PAIR "+(i%4+1)+" · "+(i<4?"DRIVER":"PASSENGER"),new Vector2(540,24),new Vector2(-20,52),17);m.menus.setupInfo.rectTransform.anchoredPosition=new Vector2(0,-332);m.menus.setupInfo.fontSizeMax=18;SportsUIAuthoring.Button(m.menus.pages[0].transform,"TEAM NAMES","teamsetup",new Vector2(0,-268),new Vector2(400,42));var pages=new GameObject[9];System.Array.Copy(m.menus.pages,pages,8);m.menus.pages=pages;var page=SportsUIAuthoring.Page("Team names",m.menus.transform,"NAME YOUR PAIRS","Individual names, colors and sources remain in participant setup");pages[8]=page;m.teamInputs=new TMP_InputField[4];for(int i=0;i<4;i++)m.teamInputs[i]=SportsUIAuthoring.Name(page.transform,"PAIR "+(i+1),m.teams[i],new Vector2(0,180-i*100));SportsUIAuthoring.Button(page.transform,"BACK TO ROLES","teamback",new Vector2(0,-330));page.SetActive(false);m.swapButton=SportsUIAuthoring.Button(m.menus.hud.transform,"SWAP DRIVER / PASSENGER","swaproles",new Vector2(280,-360),new Vector2(680,48)).gameObject;m.swapButton.SetActive(false);SportsEventAuthoring.Save(Folder);Validate();}
 static void Dress(WifeMatch m){var root=new GameObject("Partner course models and signs").transform;for(int i=0;i<60;i++){float z=i/2*12;LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,m.course.Surface(new Vector3(m.course.Center(z)+(i%2==0?-1:1)*(39+i%4*5),0,z)),i%5==0?3:7+i%4,i%5!=0,Folder);}for(int i=0;i<12;i++){float z=32+i*21;var p=m.course.Surface(new Vector3(m.course.Center(z)+(i%2==0?-19:19),0,z));SportsRallyAuthoring.Prop(root,i%3==0?"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Barrel01 Variant.prefab":"Assets/RoadPropsPack/URP/Prefabs/TireStacked01_URP.prefab",p,new Vector3(2.2f,2.2f,2.2f));var collision=new GameObject("Solid slalom island "+i);collision.transform.position=p+Vector3.up*.6f;var shape=collision.AddComponent<BoxCollider>();shape.size=new Vector3(2.2f,1.2f,2.2f);}for(int i=0;i<2;i++){float z=83+i*104;var ramp=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckTerrierRacing/Prefabs/Timber launch ramp.prefab"));ramp.name="Optional low timber balance ramp "+i;ramp.transform.SetParent(root);float x=m.course.Center(z)+(i==0?-22:22);var toe=m.course.Surface(new Vector3(x,0,z-4.5f));var rear=m.course.Surface(new Vector3(x,0,z+4.5f));ramp.transform.SetPositionAndRotation((toe+rear)*.5f-Vector3.up*.055f,Quaternion.LookRotation(rear-toe,Vector3.up));ramp.transform.localScale=new Vector3(1.7f,.28f,1.5f);foreach(var marker in ramp.GetComponentsInChildren<LWS.TruckTerrierRacing.TerrierJumpObstacle>())UnityEngine.Object.DestroyImmediate(marker);}for(int cp=0;cp<5;cp++){float z=m.course.checkpoints[cp];for(int side=-1;side<=1;side+=2){var pos=m.course.Surface(new Vector3(m.course.Center(z)+side*32,0,z));SportsRallyAuthoring.Prop(root,"Assets/RoadPropsPack/URP/Prefabs/TrafficCone_URP.prefab",pos,new Vector3(2,3,2));var t=SportsEventAuthoring.Label("Ordered partner flag "+cp,cp==4?"FINISH":"FLAG "+(cp+1),pos+Vector3.up*4,.19f,Color.white);t.gameObject.AddComponent<SportsPerCameraBillboard>();}}var water=GameObject.CreatePrimitive(PrimitiveType.Plane);water.name="Visible shallow muddy water crossing";UnityEngine.Object.DestroyImmediate(water.GetComponent<Collider>());water.transform.position=m.course.Surface(new Vector3(0,0,216))+Vector3.up*.13f;water.transform.localScale=new Vector3(6.4f,1,1.9f);water.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckDockDiving/Materials/Pool water.mat");}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<WifeMatch>();if(m==null||m.pairs.Length!=4||m.teamInputs.Length!=4||m.views.trucks.Length!=4)throw new Exception("Wife scene references incomplete");foreach(var p in m.pairs)if(p.passenger.wheels.Any(w=>w.enabled)||p.passenger.transform.localScale.x>=.8f||p.cradle==null||p.straps.Length!=2)throw new Exception("Small nonpowered roof passenger/cradle missing");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Wife one listener required");Debug.Log("WIFE_SAVED_VALIDATED four physical driver/passenger pairs");}
